display_content.json_block:
{
  "paper": "1402.0841",
  "queries": [
    "How is the shape potential written on the shape sphere and in what coordinates (w1,w2,w3)? Who is credited for the shape sphere and the Jacobi-Maupertuis metric?",
    "What is said about the figure-eight, braids, and who discovered it (Moore, Chenciner-Montgomery)?",
    "What is said about collisions, Sundman, Saari, and the measure of the collision set?",
    "What are the references cited for Lemaitre, Hsiang, Moeckel, and syzygy sequences?"
  ]
}

input.command:
cd /home/claude && pandoc essay.md -o essay.html --standalone --resource-path=/mnt/user-data/outputs --metadata title="The Three-Body Problem for Unknown Masses" -c /dev/null 2>/dev/null; cat > style.css << 'EOF'
body{font-family:"DejaVu Serif",serif;font-size:11pt;line-height:1.45;max-width:7in;margin:auto;color:#111}
h1{font-size:20pt;border-bottom:1px solid #999;padding-bottom:4px}h2{font-size:14pt;margin-top:1.4em}h3{font-size:12pt}
table{border-collapse:collapse;font-size:9.5pt;margin:8px 0}th,td{border:1px solid #999;padding:3px 6px;vertical-align:top}th{background:#eee}
pre{font-family:"DejaVu Sans Mono",monospace;font-size:8.5pt;background:#f5f5f5;padding:8px;border:1px solid #ccc;white-space:pre-wrap}
code{font-family:"DejaVu Sans Mono",monospace;font-size:9.5pt}img{max-width:100%;display:block;margin:10px auto}blockquote{border-left:3px solid #999;margin-left:0;padding-left:12px;color:#333}
EOF
sed -i 's|</head>|<style>'"$(tr -d '\n' < style.css)"'</style></head>|' essay.html
sed -i 's|src="fig|src="/mnt/user-data/outputs/fig|g' essay.html
wkhtmltopdf --enable-local-file-access -q --page-size Letter --margin-top 20mm --margin-bottom 20mm --margin-left 18mm --margin-right 18mm --footer-center "[page]" --footer-font-size 8 essay.html /mnt/user-data/outputs/DRAFT1_Three_Body_Solution_Essay.pdf 2>&1 | tail -3; python3 -c "from pypdf import PdfReader;print('pages',len(PdfReader('/mnt/user-data/outputs/DRAFT1_Three_Body_Solution_Essay.pdf').pages))"

